    logic [AW-1:0]          p_addr;
    logic signed [SW-1:0]   p_value;
    logic signed [ACCW-1:0] rq_in;
    logic signed [SW-1:0]   rq_out, st_value;
    logic                   dbg_sel;
    logic                   load_we;
    // ---- one shared multiplier: both operands are extended to LPROD first ----
    // `mem_rdata` is the registered read of the element whose flags sit in q_*:
    // the address stage of cycle k presents act_mem's address and the weight ROM's
    // address for element k, both land in `mem_rdata`/`w_data` for cycle k+1, and the
    // q_* flags were registered from that same cycle - so an extra operand register
    // would hold element k-1 and drift from the flags it is paired with.
    always_comb begin x_ext = mem_rdata; w_ext = w_data; end
    assign lane_prod = x_ext * w_ext;
    wire signed [ACCW-1:0] prod_acc = lane_prod[ACCW-1:0];
    wire signed [ACCW-1:0] acc_base = q_first ? b_data : acc;
    wire signed [ACCW-1:0] acc_next = acc_base + (q_zero ? ACC_ZERO : prod_acc);
    // ---- one shared requantizer behind the store pipeline ----
    assign st_kind = el_store ? KIND_ADD : q_kind;
    always_comb begin
        rq_in = sx(mem_rdata);
        if (st_kind == KIND_ACC) rq_in = acc_next;
    end
    assign rq_out = rq(rq_in, m_data, q_sh, q_lo, q_hi);
    always_comb begin
        unique case (st_kind)
            KIND_ACC:   st_value = rq_out;
            KIND_RQ:    st_value = rq_out;
            KIND_COPY:  st_value = mem_rdata;
            KIND_CLAMP: st_value = cl16(mem_rdata, q_lo, q_hi);
            KIND_ADD:   st_value = a_hold + rq_out;
            default:    st_value = rq_out;
        endcase
    end
    wire store_capture = (q_valid && q_last) || el_store;
    // ---- ports ----
    assign load_we = (state == S_LOAD) && in_valid && in_ready;
    assign mem_wen   = load_we || p_valid;
    assign mem_waddr = load_we ? (IN_BASE + li) : p_addr;
    assign mem_wdata = load_we ? {{8{in_data[7]}}, in_data} : p_value;
    assign dbg_sel = dbg_en && ((state == S_IDLE) || (state == S_HOLD));
    assign mem_raddr = dbg_sel ? dbg_addr : el_mem_addr;
    assign mem_ren   = dbg_sel ? 1'b1 : el_ren;
    assign w_addr = el_w_addr;
    assign b_addr = el_b_addr;
    assign m_addr = el_m_addr;
    assign dbg_data = dbg_sel ? mem_rdata : {SW{1'b0}};
    assign dbg_held = (state == S_HOLD);
    assign in_ready = (state == S_LOAD);
    assign out_valid = (state == S_OUT) && out_ph;
    assign out_data = mem_rdata[7:0];
    assign done = done_r;

    // ---- schedule control: one read port and one store port, muxed per step ----
    always_comb begin
        el_valid = 1'b0; el_ren = 1'b0; el_zero = 1'b0;
        el_first = 1'b0; el_last = 1'b0; el_store = 1'b0; el_a_capture = 1'b0;
        el_kind = KIND_ACC; el_sh = 5'd0; el_lo = 16'sd0; el_hi = 16'sd0;
        el_mem_addr = '0; el_w_addr = '0; el_b_addr = '0; el_m_addr = '0; el_st_addr = '0;
        unique case (state)
            S_LOAD: begin end
            S_OP0: begin
                if (eof == 2'd0) begin
                    el_valid = 1'b1;
                    el_first = (ic == 0) && (t == 0);
                    el_last  = (ic == S0_ICG-1) && (t == S0_TAPS-1);
                    el_kind  = KIND_ACC;
                    el_lo = S0_LO; el_hi = S0_HI; el_sh = S0_SHIFT;
                    el_m_addr = S0_MB + oc;
                    el_b_addr = S0_BB + oc;
                    el_w_addr = S0_WB + ((oc*S0_ICG + ic)*S0_TAPS + t);
                    sy0 = 0; sx0 = 0; ok0 = 1'b1;
                    unique case (t)
                        0: begin
                            sy0 = cy*1 + (-1);
                            sx0 = cx*1 + (-1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 6) sy0 = 10 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 6) sx0 = 10 - sx0;
                            ok0 = 1'b1;
                        end
                        1: begin
                            sy0 = cy*1 + (-1);
                            sx0 = cx*1 + (0);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 6) sy0 = 10 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 6) sx0 = 10 - sx0;
                            ok0 = 1'b1;
                        end
                        2: begin
                            sy0 = cy*1 + (-1);
                            sx0 = cx*1 + (1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 6) sy0 = 10 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 6) sx0 = 10 - sx0;
                            ok0 = 1'b1;
                        end
                        3: begin
                            sy0 = cy*1 + (0);
                            sx0 = cx*1 + (-1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 6) sy0 = 10 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 6) sx0 = 10 - sx0;
                            ok0 = 1'b1;
                        end
                        4: begin
                            sy0 = cy*1 + (0);
                            sx0 = cx*1 + (0);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 6) sy0 = 10 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 6) sx0 = 10 - sx0;
                            ok0 = 1'b1;
                        end
                        5: begin
                            sy0 = cy*1 + (0);
                            sx0 = cx*1 + (1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 6) sy0 = 10 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 6) sx0 = 10 - sx0;
                            ok0 = 1'b1;
                        end
                        6: begin
                            sy0 = cy*1 + (1);
                            sx0 = cx*1 + (-1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 6) sy0 = 10 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 6) sx0 = 10 - sx0;
                            ok0 = 1'b1;
                        end
                        7: begin
                            sy0 = cy*1 + (1);
                            sx0 = cx*1 + (0);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 6) sy0 = 10 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 6) sx0 = 10 - sx0;
                            ok0 = 1'b1;
                        end
                        8: begin
                            sy0 = cy*1 + (1);
                            sx0 = cx*1 + (1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 6) sy0 = 10 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 6) sx0 = 10 - sx0;
                            ok0 = 1'b1;
                        end
                        default: begin ok0 = 1'b0; sy0 = 0; sx0 = 0; end
                    endcase
                    el_zero = ~ok0;
                    el_mem_addr = ok0 ? (S0_IB + (ic*S0_IH + sy0)*S0_IW + sx0) : '0;
                    el_ren = 1'b1;
                    el_st_addr = S0_OB + (oc*S0_OH + cy)*S0_OW + cx;
                end
            end
            S_OP1: begin
                if (eof == 2'd0) begin
                    el_valid = 1'b1;
                    el_first = (t == 0);
                    el_last  = (t == S1_TAPS-1);
                    el_kind  = KIND_ACC;
                    el_lo = S1_LO; el_hi = S1_HI; el_sh = S1_SHIFT;
                    el_m_addr = S1_MB + oc;
                    el_b_addr = S1_BB + oc;
                    el_w_addr = S1_WB + oc*S1_TAPS + t;
                    sy1 = 0; sx1 = 0; ok1 = 1'b1;
                    unique case (t)
                        0: begin
                            sy1 = cy*1 + (-1);
                            sx1 = cx*1 + (-1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 6) sy1 = 10 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 6) sx1 = 10 - sx1;
                            ok1 = 1'b1;
                        end
                        1: begin
                            sy1 = cy*1 + (-1);
                            sx1 = cx*1 + (0);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 6) sy1 = 10 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 6) sx1 = 10 - sx1;
                            ok1 = 1'b1;
                        end
                        2: begin
                            sy1 = cy*1 + (-1);
                            sx1 = cx*1 + (1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 6) sy1 = 10 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 6) sx1 = 10 - sx1;
                            ok1 = 1'b1;
                        end
                        3: begin
                            sy1 = cy*1 + (0);
                            sx1 = cx*1 + (-1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 6) sy1 = 10 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 6) sx1 = 10 - sx1;
                            ok1 = 1'b1;
                        end
                        4: begin
                            sy1 = cy*1 + (0);
                            sx1 = cx*1 + (0);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 6) sy1 = 10 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 6) sx1 = 10 - sx1;
                            ok1 = 1'b1;
                        end
                        5: begin
                            sy1 = cy*1 + (0);
                            sx1 = cx*1 + (1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 6) sy1 = 10 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 6) sx1 = 10 - sx1;
                            ok1 = 1'b1;
                        end
                        6: begin
                            sy1 = cy*1 + (1);
                            sx1 = cx*1 + (-1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 6) sy1 = 10 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 6) sx1 = 10 - sx1;
                            ok1 = 1'b1;
                        end
                        7: begin
                            sy1 = cy*1 + (1);
                            sx1 = cx*1 + (0);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 6) sy1 = 10 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 6) sx1 = 10 - sx1;
                            ok1 = 1'b1;
                        end
                        8: begin
                            sy1 = cy*1 + (1);
                            sx1 = cx*1 + (1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 6) sy1 = 10 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 6) sx1 = 10 - sx1;
                            ok1 = 1'b1;
                        end
                        default: begin ok1 = 1'b0; sy1 = 0; sx1 = 0; end
                    endcase
                    el_zero = ~ok1;
                    el_mem_addr = ok1 ? (S1_IB + (oc*S1_IH + sy1)*S1_IW + sx1) : '0;
                    el_ren = 1'b1;
                    el_st_addr = S1_OB + (oc*S1_OH + cy)*S1_OW + cx;
                end
            end
            S_OP2: begin
                if (eof == 2'd0) begin
                    el_valid = 1'b1;
                    el_first = (ic == 0) && (t == 0);
                    el_last  = (ic == S2_ICG-1) && (t == S2_TAPS-1);
                    el_kind  = KIND_ACC;
                    el_lo = S2_LO; el_hi = S2_HI; el_sh = S2_SHIFT;
                    el_m_addr = S2_MB + oc;
                    el_b_addr = S2_BB + oc;
                    el_w_addr = S2_WB + ((oc*S2_ICG + ic)*S2_TAPS + t);
                    sy2 = 0; sx2 = 0; ok2 = 1'b1;
                    unique case (t)
                        0: begin
                            sy2 = cy*1 + (0);
                            sx2 = cx*1 + (0);
                            ok2 = (sy2 >= 0) && (sy2 < 6) && (sx2 >= 0) && (sx2 < 6);
                        end
                        default: begin ok2 = 1'b0; sy2 = 0; sx2 = 0; end
                    endcase
                    el_zero = ~ok2;
                    el_mem_addr = ok2 ? (S2_IB + (ic*S2_IH + sy2)*S2_IW + sx2) : '0;
                    el_ren = 1'b1;
                    el_st_addr = S2_OB + (oc*S2_OH + cy)*S2_OW + cx;
                end
            end
            S_OP3: begin
                if (eof == 2'd0) begin
                    el_lo = S3_LO; el_hi = S3_HI; el_sh = S3_SHIFT;
                    el_m_addr = S3_MB;
                    el_st_addr = S3_OB + (oc*S3_OH + cy)*S3_OW + cx;
                    unique case (ad_ph)
                        2'd0: begin
                            el_ren = 1'b1;
                            el_mem_addr = S3_IB + (oc*S3_IH + cy)*S3_IW + cx;
                        end
                        2'd1: begin
                            el_ren = 1'b1;
                            el_mem_addr = S3_IB2 + (oc*S3_IH + cy)*S3_IW + cx;
                            el_a_capture = 1'b1;
                        end
                        default: begin
                            el_store = 1'b1;
                            el_ren = (cx + 1 < S3_OW) || (cy + 1 < S3_OH) || (oc + 1 < S3_OC);
                            el_mem_addr = (cx + 1 < S3_OW)
                                ? (S3_IB + ((oc*S3_OH + cy)*S3_OW + cx) + 1)
                                : ((cy + 1 < S3_OH)
                                    ? (S3_IB + (oc*S3_OH + cy + 1)*S3_OW)
                                    : (S3_IB + (oc + 1)*S3_OH*S3_OW));
                        end
                    endcase
                end
            end
            S_OP4: begin
                if (eof == 2'd0) begin
                    el_valid = 1'b1;
                    el_first = 1'b1; el_last = 1'b1;
                    el_kind = KIND_COPY;
                    el_mem_addr = S4_IB + (oc*S4_IH + (cy >> 1))*S4_IW + (cx >> 1);
                    el_ren = 1'b1;
                    el_st_addr = S4_OB + (oc*S4_OH + cy)*S4_OW + cx;
                end
            end
            S_OP5: begin
                if (eof == 2'd0) begin
                    el_valid = 1'b1;
                    el_first = (ic == 0) && (t == 0);
                    el_last  = (ic == S5_ICG-1) && (t == S5_TAPS-1);
                    el_kind  = KIND_ACC;
                    el_lo = S5_LO; el_hi = S5_HI; el_sh = S5_SHIFT;
                    el_m_addr = S5_MB + oc;
                    el_b_addr = S5_BB + oc;
                    el_w_addr = S5_WB + ((oc*S5_ICG + ic)*S5_TAPS + t);
                    sy5 = 0; sx5 = 0; ok5 = 1'b1;
                    unique case (t)
                        0: begin
                            sy5 = cy*1 + (0);
                            sx5 = cx*1 + (0);
                            ok5 = (sy5 >= 0) && (sy5 < 12) && (sx5 >= 0) && (sx5 < 12);
                        end
                        default: begin ok5 = 1'b0; sy5 = 0; sx5 = 0; end
                    endcase
                    el_zero = ~ok5;
                    el_mem_addr = ok5 ? (S5_IB + (ic*S5_IH + sy5)*S5_IW + sx5) : '0;
                    el_ren = 1'b1;
                    el_st_addr = S5_OB + (oc*S5_OH + cy)*S5_OW + cx;
                end
            end
            S_OP6: begin
                if (eof == 2'd0) begin
                    el_valid = 1'b1;
                    el_first = 1'b1; el_last = 1'b1;
                    el_kind = KIND_CLAMP;
                    el_lo = S6_LO; el_hi = S6_HI; el_sh = S6_SHIFT;
                    el_m_addr = S6_MB;
                    el_mem_addr = S6_IB + (oc*S6_IH + cy)*S6_IW + cx;
                    el_ren = 1'b1;
                    el_st_addr = S6_OB + (oc*S6_OH + cy)*S6_OW + cx;
                end
            end
            S_OUT: begin
                if (!out_ph) begin
                    el_ren = 1'b1;
                    el_mem_addr = OUT_BASE + oi;
                end
            end
            default: begin end
        endcase
    end

    // ---- static schedule FSM ----
    always_ff @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            hold_next <= S_IDLE;
            cy <= 0; cx <= 0; oc <= 0; ic <= 0; t <= 0;
            li <= 0; oi <= 0; eof <= 2'd0; ad_ph <= 2'd0; out_ph <= 1'b0;
            done_r <= 1'b0; p_valid <= 1'b0;
            acc <= ACC_ZERO; a_hold <= ACC_ZERO;
            q_valid <= 1'b0; q_first <= 1'b0; q_last <= 1'b0; q_zero <= 1'b0;
        end else begin
            // address stage -> MAC stage (one element of latency)
            q_valid <= el_valid;
            q_first <= el_first;
            q_last  <= el_last;
            q_zero  <= el_zero;
            q_kind  <= el_kind;
            q_sh    <= el_sh;
            q_lo    <= el_lo;
            q_hi    <= el_hi;
            q_sa    <= el_st_addr;
            if (el_a_capture) a_hold <= sx(mem_rdata);
            // the shared MAC stage
            if (q_valid) acc <= acc_next;
            // the one-deep store pipeline
            p_valid <= store_capture;
            if (store_capture) begin
                p_addr  <= el_store ? el_st_addr : q_sa;
                p_value <= st_value;
            end
            unique case (state)
                S_IDLE: begin
                    if (start) begin
                        done_r <= 1'b0;
                        cy <= 0; cx <= 0; oc <= 0; ic <= 0; t <= 0; li <= 0; oi <= 0;
                        eof <= 2'd0; ad_ph <= 2'd0; out_ph <= 1'b0;
                        acc <= ACC_ZERO; a_hold <= ACC_ZERO;
                        state <= S_LOAD;
                    end
                end
                S_LOAD: begin
                    if (in_valid && in_ready) begin
                        if (li + 1 == NI) begin
                            li <= 0;
                            if (dbg_hold_en) begin state <= S_HOLD; hold_next <= S_OP0; end
                            else state <= S_OP0;
                            eof <= 2'd0;
                            ad_ph <= 2'd0;
                        end else li <= li + 1;
                    end
                end
                S_HOLD: begin
                    if (dbg_cont || !dbg_hold_en) state <= hold_next;
                end
                S_OP0: begin
                    if (eof == 2'd0) begin
                        if (t + 1 < 9) t <= t + 1;
                        else begin
                            t <= 0;
                            if (ic + 1 < 3) ic <= ic + 1;
                            else begin
                                ic <= 0;
                                if (oc + 1 < 4) oc <= oc + 1;
                                else begin
                                    oc <= 0;
                                    if (cx + 1 < 6) cx <= cx + 1;
                                    else begin
                                        cx <= 0;
                                        if (cy + 1 < 6) cy <= cy + 1;
                                        else begin
                                            cy <= 0;
                                            eof <= 2'd1;
                                        end
                                    end
                                end
                            end
                        end
                    end else if (eof == 2'd1) eof <= 2'd2;
                    else begin
                        if (dbg_hold_en) begin state <= S_HOLD; hold_next <= S_OP1; end
                        else state <= S_OP1;
                        eof <= 2'd0;
                        ad_ph <= 2'd0;
                    end
                end
                S_OP1: begin
                    if (eof == 2'd0) begin
                        if (t + 1 < 9) t <= t + 1;
                        else begin
                            t <= 0;
                            if (oc + 1 < 4) oc <= oc + 1;
                            else begin
                                oc <= 0;
                                if (cx + 1 < 6) cx <= cx + 1;
                                else begin
                                    cx <= 0;
                                    if (cy + 1 < 6) cy <= cy + 1;
                                    else begin
                                        cy <= 0;
                                        eof <= 2'd1;
                                    end
                                end
                            end
                        end
                    end else if (eof == 2'd1) eof <= 2'd2;
                    else begin
                        if (dbg_hold_en) begin state <= S_HOLD; hold_next <= S_OP2; end
                        else state <= S_OP2;
                        eof <= 2'd0;
                        ad_ph <= 2'd0;
                    end
                end
                S_OP2: begin
                    if (eof == 2'd0) begin
                        if (t + 1 < 1) t <= t + 1;
                        else begin
                            t <= 0;
                            if (ic + 1 < 4) ic <= ic + 1;
                            else begin
                                ic <= 0;
                                if (oc + 1 < 4) oc <= oc + 1;
                                else begin
                                    oc <= 0;
                                    if (cx + 1 < 6) cx <= cx + 1;
                                    else begin
                                        cx <= 0;
                                        if (cy + 1 < 6) cy <= cy + 1;
                                        else begin
                                            cy <= 0;
                                            eof <= 2'd1;
                                        end
                                    end
                                end
                            end
                        end
                    end else if (eof == 2'd1) eof <= 2'd2;
                    else begin
                        if (dbg_hold_en) begin state <= S_HOLD; hold_next <= S_OP3; end
                        else state <= S_OP3;
                        eof <= 2'd0;
                        ad_ph <= 2'd0;
                    end
                end
                S_OP3: begin
                    if (eof == 2'd0) begin
                        unique case (ad_ph)
                            2'd0: ad_ph <= 2'd1;
                            2'd1: ad_ph <= 2'd2;
                            default: begin
                                ad_ph <= 2'd1;
                                if (cx + 1 < 6) cx <= cx + 1;
                                else begin
                                    cx <= 0;
                                    if (cy + 1 < 6) cy <= cy + 1;
                                    else begin
                                        cy <= 0;
                                        if (oc + 1 < 4) oc <= oc + 1;
                                        else begin
                                            oc <= 0;
                                            eof <= 2'd1;
                                        end
                                    end
                                end
                            end
                        endcase
                    end else begin
                        if (dbg_hold_en) begin state <= S_HOLD; hold_next <= S_OP4; end
                        else state <= S_OP4;
                        eof <= 2'd0;
                        ad_ph <= 2'd0;
                    end
                end
                S_OP4: begin
                    if (eof == 2'd0) begin
                        if (cx + 1 < 12) cx <= cx + 1;
                        else begin
                            cx <= 0;
                            if (cy + 1 < 12) cy <= cy + 1;
                            else begin
                                cy <= 0;
                                if (oc + 1 < 4) oc <= oc + 1;
                                else begin
                                    oc <= 0;
                                    eof <= 2'd1;
                                end
                            end
                        end
                    end else if (eof == 2'd1) eof <= 2'd2;
                    else begin
                        if (dbg_hold_en) begin state <= S_HOLD; hold_next <= S_OP5; end
                        else state <= S_OP5;
                        eof <= 2'd0;
                        ad_ph <= 2'd0;
                    end
                end
                S_OP5: begin
                    if (eof == 2'd0) begin
                        if (t + 1 < 1) t <= t + 1;
                        else begin
                            t <= 0;
                            if (ic + 1 < 4) ic <= ic + 1;
                            else begin
                                ic <= 0;
                                if (oc + 1 < 3) oc <= oc + 1;
                                else begin
                                    oc <= 0;
                                    if (cx + 1 < 12) cx <= cx + 1;
                                    else begin
                                        cx <= 0;
                                        if (cy + 1 < 12) cy <= cy + 1;
                                        else begin
                                            cy <= 0;
                                            eof <= 2'd1;
                                        end
                                    end
                                end
                            end
                        end
                    end else if (eof == 2'd1) eof <= 2'd2;
                    else begin
                        if (dbg_hold_en) begin state <= S_HOLD; hold_next <= S_OP6; end
                        else state <= S_OP6;
                        eof <= 2'd0;
                        ad_ph <= 2'd0;
                    end
                end
                S_OP6: begin
                    if (eof == 2'd0) begin
                        if (cx + 1 < 12) cx <= cx + 1;
                        else begin
                            cx <= 0;
                            if (cy + 1 < 12) cy <= cy + 1;
                            else begin
                                cy <= 0;
                                if (oc + 1 < 3) oc <= oc + 1;
                                else begin
                                    oc <= 0;
                                    eof <= 2'd1;
                                end
                            end
                        end
                    end else if (eof == 2'd1) eof <= 2'd2;
                    else begin
                        if (dbg_hold_en) begin state <= S_HOLD; hold_next <= S_OUT; end
                        else state <= S_OUT;
                        eof <= 2'd0;
                        ad_ph <= 2'd0;
                        out_ph <= 1'b0;
                    end
                end
                S_OUT: begin
                    if (!out_ph) out_ph <= 1'b1;
                    else if (out_ready) begin
                        if (oi + 1 < NO) begin
                            oi <= oi + 1; out_ph <= 1'b0;
                        end else begin
                            oi <= 0; out_ph <= 1'b0; done_r <= 1'b1;
                            state <= S_IDLE;
                        end
                    end
                end
                default: state <= S_IDLE;
            endcase
        end
    end
    // state width: 4 bits
endmodule
`default_nettype wire
